from __future__ import annotations

import re

_ALIGNS = (None, "left", "right", "center")
_PIPE = re.compile(r"(?<!\\)\|")
_DELIMITER = re.compile(r":?-+:?")


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def _pad(text: str, width: int, align: str | None) -> str:
    space = width - len(text)
    if align == "right":
        return " " * space + text
    if align == "center":
        return " " * (space // 2) + text + " " * (space - space // 2)
    return text + " " * space


def _dashes(width: int, align: str | None) -> str:
    left = ":" if align in ("left", "center") else "-"
    right = ":" if align in ("right", "center") else "-"
    return left + "-" * (width - 2) + right


def _cells(line: str) -> list[str]:
    line = line.strip()
    if line.startswith("|"):
        line = line[1:]
    if line.endswith("|") and not line.endswith("\\|"):
        line = line[:-1]
    return [cell.strip().replace("\\|", "|") for cell in _PIPE.split(line)]


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    n = len(header)
    align = [None] * n if align is None else list(align)
    if len(align) != n or any(a not in _ALIGNS for a in align):
        raise ValueError(f"bad alignment: {align!r}")
    table = [list(header)]
    for row in rows:
        if len(row) > n:
            raise ValueError(f"row has more than {n} cells: {row!r}")
        table.append(list(row) + [None] * (n - len(row)))
    table = [
        ["" if v is None else str(v).replace("|", "\\|") for v in row]
        for row in table
    ]
    widths = [max([3] + [len(row[i]) for row in table]) for i in range(n)]
    lines = [
        _line([_pad(c, w, a) for c, w, a in zip(row, widths, align)])
        for row in table
    ]
    lines.insert(1, _line([_dashes(w, a) for w, a in zip(widths, align)]))
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.strip().splitlines()
    if len(lines) < 2:
        raise ValueError("a table needs a header and a delimiter line")
    header = _cells(lines[0])
    delimiter = _cells(lines[1])
    if len(delimiter) != len(header) or not all(
        _DELIMITER.fullmatch(cell) for cell in delimiter
    ):
        raise ValueError(f"bad delimiter line: {lines[1]!r}")
    align = [
        {(True, True): "center", (True, False): "left", (False, True): "right"}.get(
            (cell.startswith(":"), cell.endswith(":"))
        )
        for cell in delimiter
    ]
    rows = []
    for line in lines[2:]:
        row = _cells(line)
        if len(row) != len(header):
            raise ValueError(f"row has {len(row)} cells, not {len(header)}: {line!r}")
        rows.append(row)
    return header, rows, align

